function validate([expression]) {
  if (typeof expression !== 'string') return 'expression must be a string.';
  if (expression.length < 5 || expression.length > 10000) return 'expression has 5 to 10^4 characters.';
  let open = 0;
  for (let i = 0; i < expression.length; i++) {
    const ch = expression[i];
    if (i % 2 === 0) {
      if (!/[0-9TF]/.test(ch)) return 'Values (digits, T or F) and the symbols ? and : must alternate.';
    } else if (ch === '?') {
      if (expression[i - 1] !== 'T' && expression[i - 1] !== 'F') return 'Every condition before ? must be T or F.';
      open++;
    } else if (ch === ':') {
      if (--open < 0) return 'Every : needs a matching ? before it.';
    } else return 'Values (digits, T or F) and the symbols ? and : must alternate.';
  }
  if (expression.length % 2 === 0 || open !== 0) return 'Every ? needs a matching :.';
  return null;
}

