function parseTernary(expression) {
  const stack = [];
  for (let i = expression.length - 1; i >= 0; i--) {
    const ch = expression[i];
    if (ch === ':') {
      continue;
    }
    if (ch === '?') {
      const onTrue = stack.pop();
      const onFalse = stack.pop();
      i--;
      stack.push(expression[i] === 'T' ? onTrue : onFalse);
    } else {
      stack.push(ch);
    }
  }
  return stack.pop();
}

