function parseTernary(expression) {
  // Repeatedly collapse the rightmost "c?x:y": after the last '?' both branches are single values.
  let s = expression;
  while (s.length > 1) {
    const q = s.lastIndexOf('?');
    const value = s[q - 1] === 'T' ? s[q + 1] : s[q + 3];
    s = s.slice(0, q - 1) + value + s.slice(q + 4);
  }
  return s;
}

