function generate(rand, size) {
  const values = '0123456789TF';
  const pick = text => text[Math.floor(rand() * text.length)];
  const ops = size === 'large' ? 1500 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 5);
  const shape = Math.floor(rand() * 3);
  // Build a tree with the requested number of conditionals; the shape decides where nested ones go.
  const build = count => {
    if (count === 0) return pick(values);
    let inTrue;
    if (shape === 0) inTrue = Math.floor(rand() * count);
    else if (shape === 1) inTrue = rand() < 0.8 ? 0 : Math.floor(rand() * count);
    else inTrue = rand() < 0.8 ? count - 1 : Math.floor(rand() * count);
    return pick('TF') + '?' + build(inTrue) + ':' + build(count - 1 - inTrue);
  };
  return [build(ops)];
}
